<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {authClient,errorMessage} from '../api';import {useAuth} from '../stores/auth';
const username=ref(''),password=ref(''),busy=ref(false),error=ref(''),router=useRouter(),auth=useAuth();
async function login(){error.value='';busy.value=true;try{const result=await authClient.signIn.username({username:username.value,password:password.value});if(result.error)throw new Error(result.error.status===429?'Demasiados intentos. Espera un minuto y vuelve a intentar.':'No se pudo iniciar sesión. Revisa tus credenciales y el estado de tu cuenta.');await auth.load();if(!auth.user)throw new Error('No se pudo recuperar la sesión. Revisa la conexión.');password.value='';router.replace(auth.user.mustChangePassword?'/cuenta':auth.user.role==='preparacion'?'/comandas':'/dashboard');}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
</script>
<template><main class="login-page"><form class="login-card stack" @submit.prevent="login"><p class="login-brand">BRIOCHETT</p><h1>Inicia sesión con tu cuenta</h1><p class="muted">Gestión comercial y seguimiento de pedidos.</p><p v-if="error" class="notice error" role="alert">{{error}}</p><label>Usuario<input v-model="username" autocomplete="username" required autocapitalize="none" spellcheck="false" maxlength="40" /></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required maxlength="128" /></label><button :disabled="busy">{{busy?'Ingresando…':'Ingresar'}}</button><p class="muted small">El acceso y el rol de tu cuenta los gestiona Administración.</p></form></main></template>
